export async function drainSpool(
  deliver: (env: DispatchEnvelope) => Promise<void> | void,
): Promise<void> {
  const dir = getSpoolDir()
  if (!existsSync(dir)) return
  let entries: string[]
  try {
    entries = readdirSync(dir)
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return
