      if (!existsSync(path)) return
      void ingestEnvelope(path, deliver).catch(() => {})
    })
    watcher.on('error', e => {
      logEvent('tengu_bg_dispatch_watcher_failed', {
        errno: (e as NodeJS.ErrnoException).code ?? 'unknown',
      })
    })
  } catch (e) {
    logEvent('tengu_bg_dispatch_watcher_failed', {
      errno: (e as NodeJS.ErrnoException).code ?? 'unknown',
      reason: 'watch-setup',
    })
  }
